import React, { useState, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Search, Shield, ShieldOff, UserCheck, UserX, Eye, Users,
  ChevronLeft, ChevronRight, X, Crown, Phone, Mail, CalendarDays,
} from 'lucide-react';
import toast from 'react-hot-toast';

const mockUsers = [
  { id: 1, name: 'Arjun Sharma', email: 'arjun@email.com', phone: '+91-9876543210', role: 'user', status: 'active', bookings: 8, joined: '2025-06-15', avatar: null },
  { id: 2, name: 'Priya Patel', email: 'priya@email.com', phone: '+91-9876543211', role: 'user', status: 'active', bookings: 5, joined: '2025-07-20', avatar: null },
  { id: 3, name: 'Rahul Gupta', email: 'rahul@email.com', phone: '+91-9876543212', role: 'agent', status: 'active', bookings: 42, joined: '2025-01-10', avatar: null },
  { id: 4, name: 'Ananya Singh', email: 'ananya@email.com', phone: '+91-9876543213', role: 'user', status: 'blocked', bookings: 1, joined: '2025-09-05', avatar: null },
  { id: 5, name: 'Vikram Reddy', email: 'vikram@email.com', phone: '+91-9876543214', role: 'vendor', status: 'active', bookings: 0, joined: '2025-03-22', avatar: null },
  { id: 6, name: 'Kavya Nair', email: 'kavya@email.com', phone: '+91-9876543215', role: 'user', status: 'active', bookings: 3, joined: '2025-11-18', avatar: null },
  { id: 7, name: 'Rohan Mehta', email: 'rohan@email.com', phone: '+91-9876543216', role: 'admin', status: 'active', bookings: 0, joined: '2024-12-01', avatar: null },
  { id: 8, name: 'Divya Joshi', email: 'divya@email.com', phone: '+91-9876543217', role: 'user', status: 'active', bookings: 12, joined: '2025-08-14', avatar: null },
  { id: 9, name: 'Aditya Kumar', email: 'aditya@email.com', phone: '+91-9876543218', role: 'agent', status: 'active', bookings: 67, joined: '2025-02-28', avatar: null },
  { id: 10, name: 'Sneha Iyer', email: 'sneha@email.com', phone: '+91-9876543219', role: 'user', status: 'active', bookings: 6, joined: '2025-10-07', avatar: null },
];

const ROLE_CONFIG = {
  admin: { label: 'Admin', classes: 'bg-purple-100 text-purple-700', icon: Crown },
  agent: { label: 'Agent', classes: 'bg-blue-100 text-blue-700', icon: Shield },
  vendor: { label: 'Vendor', classes: 'bg-orange-100 text-orange-700', icon: Shield },
  user: { label: 'User', classes: 'bg-gray-100 text-gray-600', icon: UserCheck },
};

const STATUS_CONFIG = {
  active: { label: 'Active', classes: 'bg-emerald-100 text-emerald-700' },
  blocked: { label: 'Blocked', classes: 'bg-red-100 text-red-700' },
};

const ROLES = ['all', 'user', 'agent', 'vendor', 'admin'];

const UserDetailModal = ({ user, onClose, onToggleBlock, onPromote }) => (
  <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 bg-black/50 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4">
    <motion.div initial={{ y: '100%' }} animate={{ y: 0 }} exit={{ y: '100%' }} transition={{ type: 'spring', damping: 25 }} className="bg-white rounded-t-3xl sm:rounded-2xl w-full sm:max-w-md shadow-2xl">
      <div className="flex items-center justify-between p-5 border-b border-gray-100">
        <h3 className="text-lg font-bold text-gray-900">User Details</h3>
        <button onClick={onClose} className="text-gray-400 hover:text-gray-600"><X className="w-5 h-5" /></button>
      </div>
      <div className="p-5 space-y-5">
        {/* Avatar & Name */}
        <div className="flex items-center gap-4">
          <div className="w-16 h-16 rounded-2xl bg-gradient-to-br from-[#0B4F6C] to-[#00B4D8] flex items-center justify-center text-white text-2xl font-bold">
            {user.name.charAt(0)}
          </div>
          <div>
            <h4 className="text-lg font-bold text-gray-900">{user.name}</h4>
            <div className="flex items-center gap-2 mt-1">
              <span className={`px-2.5 py-0.5 rounded-full text-xs font-semibold ${ROLE_CONFIG[user.role]?.classes}`}>{ROLE_CONFIG[user.role]?.label}</span>
              <span className={`px-2.5 py-0.5 rounded-full text-xs font-semibold ${STATUS_CONFIG[user.status]?.classes}`}>{STATUS_CONFIG[user.status]?.label}</span>
            </div>
          </div>
        </div>

        {/* Details */}
        <div className="bg-gray-50 rounded-xl p-4 space-y-3">
          {[
            { icon: Mail, label: 'Email', value: user.email },
            { icon: Phone, label: 'Phone', value: user.phone },
            { icon: CalendarDays, label: 'Joined', value: new Date(user.joined).toLocaleDateString('en-IN', { day: 'numeric', month: 'long', year: 'numeric' }) },
            { icon: Users, label: 'Bookings', value: `${user.bookings} bookings made` },
          ].map(({ icon: Icon, label, value }) => (
            <div key={label} className="flex items-center gap-3">
              <div className="w-7 h-7 bg-white rounded-lg shadow-sm flex items-center justify-center flex-shrink-0">
                <Icon className="w-3.5 h-3.5 text-gray-400" />
              </div>
              <div>
                <p className="text-xs text-gray-500">{label}</p>
                <p className="text-sm font-medium text-gray-800">{value}</p>
              </div>
            </div>
          ))}
        </div>

        {/* Actions */}
        <div className="flex flex-col gap-2">
          {user.role === 'user' && (
            <button onClick={() => onPromote(user.id)} className="w-full py-2.5 bg-blue-600 text-white text-sm font-semibold rounded-lg hover:bg-blue-700 transition-colors flex items-center justify-center gap-2">
              <Crown className="w-4 h-4" /> Promote to Agent
            </button>
          )}
          <button onClick={() => onToggleBlock(user.id)} className={`w-full py-2.5 text-white text-sm font-semibold rounded-lg transition-colors flex items-center justify-center gap-2 ${user.status === 'active' ? 'bg-red-500 hover:bg-red-600' : 'bg-emerald-600 hover:bg-emerald-700'}`}>
            {user.status === 'active' ? <><UserX className="w-4 h-4" /> Block User</> : <><UserCheck className="w-4 h-4" /> Unblock User</>}
          </button>
        </div>
      </div>
    </motion.div>
  </motion.div>
);

const AdminUserManagementPage = () => {
  const [users, setUsers] = useState(mockUsers);
  const [search, setSearch] = useState('');
  const [roleFilter, setRoleFilter] = useState('all');
  const [statusFilter, setStatusFilter] = useState('all');
  const [selectedUser, setSelectedUser] = useState(null);
  const [currentPage, setCurrentPage] = useState(1);
  const perPage = 8;

  const filtered = useMemo(() => {
    return users.filter((u) => {
      const matchSearch = u.name.toLowerCase().includes(search.toLowerCase()) ||
        u.email.toLowerCase().includes(search.toLowerCase());
      const matchRole = roleFilter === 'all' || u.role === roleFilter;
      const matchStatus = statusFilter === 'all' || u.status === statusFilter;
      return matchSearch && matchRole && matchStatus;
    });
  }, [users, search, roleFilter, statusFilter]);

  const totalPages = Math.ceil(filtered.length / perPage);
  const paginated = filtered.slice((currentPage - 1) * perPage, currentPage * perPage);

  const toggleBlock = (id) => {
    setUsers((prev) => prev.map((u) => u.id === id ? { ...u, status: u.status === 'active' ? 'blocked' : 'active' } : u));
    const user = users.find((u) => u.id === id);
    toast.success(`${user?.name} ${user?.status === 'active' ? 'blocked' : 'unblocked'}`);
    setSelectedUser((prev) => prev ? { ...prev, status: prev.status === 'active' ? 'blocked' : 'active' } : null);
  };

  const promoteToAgent = (id) => {
    setUsers((prev) => prev.map((u) => u.id === id ? { ...u, role: 'agent' } : u));
    const user = users.find((u) => u.id === id);
    toast.success(`${user?.name} promoted to Agent`);
    setSelectedUser(null);
  };

  return (
    <div className="min-h-screen bg-gray-50 p-4 sm:p-6 lg:p-8">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">User Management</h1>
          <p className="text-sm text-gray-500">{users.length} registered users</p>
        </div>
      </div>

      {/* Role Stat Cards */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 mb-5">
        {ROLES.filter((r) => r !== 'all').map((role) => {
          const count = users.filter((u) => u.role === role).length;
          const cfg = ROLE_CONFIG[role];
          return (
            <div key={role} className="bg-white rounded-xl border border-gray-100 shadow-sm p-4">
              <p className="text-xl font-bold text-gray-900">{count}</p>
              <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-semibold mt-1 ${cfg.classes}`}>{cfg.label}s</span>
            </div>
          );
        })}
      </div>

      {/* Filters */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 mb-5">
        <div className="flex flex-col sm:flex-row gap-3">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
            <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search by name or email..." className="w-full pl-9 pr-3 py-2.5 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-[#0B4F6C]/30 focus:border-[#0B4F6C]" />
          </div>
          <select value={roleFilter} onChange={(e) => setRoleFilter(e.target.value)} className="border border-gray-200 rounded-lg px-3 py-2.5 text-sm focus:outline-none bg-white">
            {ROLES.map((r) => <option key={r} value={r}>{r === 'all' ? 'All Roles' : ROLE_CONFIG[r]?.label}</option>)}
          </select>
          <select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)} className="border border-gray-200 rounded-lg px-3 py-2.5 text-sm focus:outline-none bg-white">
            <option value="all">All Status</option>
            <option value="active">Active</option>
            <option value="blocked">Blocked</option>
          </select>
        </div>
      </div>

      {/* Table */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead>
              <tr className="border-b border-gray-100 bg-gray-50/50">
                <th className="text-left text-xs font-semibold text-gray-500 uppercase tracking-wider px-4 py-3">User</th>
                <th className="text-left text-xs font-semibold text-gray-500 uppercase tracking-wider px-4 py-3 hidden md:table-cell">Contact</th>
                <th className="text-center text-xs font-semibold text-gray-500 uppercase tracking-wider px-4 py-3">Role</th>
                <th className="text-center text-xs font-semibold text-gray-500 uppercase tracking-wider px-4 py-3">Status</th>
                <th className="text-center text-xs font-semibold text-gray-500 uppercase tracking-wider px-4 py-3 hidden sm:table-cell">Bookings</th>
                <th className="text-left text-xs font-semibold text-gray-500 uppercase tracking-wider px-4 py-3 hidden lg:table-cell">Joined</th>
                <th className="text-center text-xs font-semibold text-gray-500 uppercase tracking-wider px-4 py-3">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {paginated.map((user, index) => (
                <motion.tr key={user.id} initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: index * 0.04 }} className="hover:bg-gray-50/50 transition-colors">
                  <td className="px-4 py-4">
                    <div className="flex items-center gap-3">
                      <div className="w-9 h-9 rounded-full bg-gradient-to-br from-[#0B4F6C] to-[#00B4D8] flex items-center justify-center text-white text-sm font-bold flex-shrink-0">{user.name.charAt(0)}</div>
                      <div>
                        <p className="text-sm font-semibold text-gray-800">{user.name}</p>
                        <p className="text-xs text-gray-500 hidden sm:block">{user.email}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-4 py-4 hidden md:table-cell">
                    <p className="text-xs text-gray-600">{user.email}</p>
                    <p className="text-xs text-gray-500">{user.phone}</p>
                  </td>
                  <td className="px-4 py-4 text-center">
                    <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold ${ROLE_CONFIG[user.role]?.classes}`}>{ROLE_CONFIG[user.role]?.label}</span>
                  </td>
                  <td className="px-4 py-4 text-center">
                    <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold ${STATUS_CONFIG[user.status]?.classes}`}>{STATUS_CONFIG[user.status]?.label}</span>
                  </td>
                  <td className="px-4 py-4 text-center hidden sm:table-cell">
                    <span className="text-sm font-medium text-gray-700">{user.bookings}</span>
                  </td>
                  <td className="px-4 py-4 hidden lg:table-cell">
                    <span className="text-sm text-gray-600">{new Date(user.joined).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })}</span>
                  </td>
                  <td className="px-4 py-4">
                    <div className="flex items-center justify-center gap-1">
                      <button onClick={() => setSelectedUser(user)} className="p-1.5 text-gray-400 hover:text-[#0B4F6C] hover:bg-blue-50 rounded-lg transition-colors"><Eye className="w-4 h-4" /></button>
                      <button onClick={() => toggleBlock(user.id)} className={`p-1.5 rounded-lg transition-colors ${user.status === 'active' ? 'text-gray-400 hover:text-red-500 hover:bg-red-50' : 'text-gray-400 hover:text-emerald-600 hover:bg-emerald-50'}`}>
                        {user.status === 'active' ? <UserX className="w-4 h-4" /> : <UserCheck className="w-4 h-4" />}
                      </button>
                    </div>
                  </td>
                </motion.tr>
              ))}
            </tbody>
          </table>
        </div>

        {totalPages > 1 && (
          <div className="px-4 py-3 border-t border-gray-100 flex items-center justify-between">
            <p className="text-sm text-gray-500">Showing {(currentPage - 1) * perPage + 1}–{Math.min(currentPage * perPage, filtered.length)} of {filtered.length}</p>
            <div className="flex gap-1">
              <button disabled={currentPage === 1} onClick={() => setCurrentPage((p) => p - 1)} className="p-1.5 border border-gray-200 rounded-lg disabled:opacity-40 hover:bg-gray-50"><ChevronLeft className="w-4 h-4" /></button>
              <button disabled={currentPage === totalPages} onClick={() => setCurrentPage((p) => p + 1)} className="p-1.5 border border-gray-200 rounded-lg disabled:opacity-40 hover:bg-gray-50"><ChevronRight className="w-4 h-4" /></button>
            </div>
          </div>
        )}
      </div>

      <AnimatePresence>
        {selectedUser && (
          <UserDetailModal user={selectedUser} onClose={() => setSelectedUser(null)} onToggleBlock={toggleBlock} onPromote={promoteToAgent} />
        )}
      </AnimatePresence>
    </div>
  );
};

export default AdminUserManagementPage;
